    /**
     * Get the blacklist
     * @param params - Optional query parameters
     * @param params.type - Filter type, defaults to 'all'
     * @param params.page - Page number, starting from 1
     * @param params.limit - Items per page limit
     * @returns Blacklist and pagination information
     */
    public async getBlacklist(params?: { type?: string; page?: number; limit?: number }): Promise<IBlacklistResponse> {
        const mappedParams = mapParams((params || {}) as unknown as Record<string, unknown>, "admin");
        if (mappedParams.limit !== undefined) {
            mappedParams.limit = sanitizeLimit(mappedParams.limit as number);
        }
        mappedParams.type = mappedParams.type || "all";

        const response = await this.httpClient.get<{
            status: string;
            data?: IBlacklistResponse;
            error?: string;
        }>(SynapseAdminApi.BLACKLIST_LIST, mappedParams);

        const data = handleApiResponse(response, "Failed to get blacklist");
        return data?.blacklist
            ? {
                  blacklist: data.blacklist,
                  pagination: data.pagination || { page: 1, limit: 20, total: 0, total_pages: 0 },
              }
            : { blacklist: [], pagination: { page: 1, limit: 20, total: 0, total_pages: 0 } };
    }

