    /**
     * Get user list
     * @param params - Optional query parameters
     * @param params.page - Page number, starting from 1
     * @param params.limit - Items per page limit
     * @param params.search - Search keyword
     * @returns User list and pagination information
     */
    public async getUsers(params?: IAdminParams): Promise<IAdminPaginationResult<IAdminUser>> {
        const queryParams: Record<string, unknown> = {};

        if (params?.page !== undefined) {
            queryParams.page = params.page;
        }
        if (params?.limit !== undefined) {
            queryParams.limit = params.limit;
        }
        if (params?.search) {
            queryParams.search = params.search;
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                items?: IAdminUser[];
                total?: number;
                page?: number;
                limit?: number;
            };
            error?: string;
        }>(SynapseAdminApi.USERS, queryParams);

        handleApiResponse(response, "Failed to get users");

        const result = extractItemsFromDataResponse(response);
        const returnValue: IAdminPaginationResult<IAdminUser> = {
            items: result.items as IAdminUser[],
            total: result.total,
            offset: (result.page - 1) * result.limit,
            limit: result.limit,
            pagination: {
                page: result.page,
                total_pages: Math.ceil(result.total / result.limit),
                has_next: result.page * result.limit < result.total,
                has_before: result.page > 1,
            },
        };
        return returnValue;
    }

    /**
     * Get user details
     * @param userId - User ID
     * @returns User details, null if user doesn't exist
     */
    public async getUserDetail(userId: string): Promise<IAdminUser | null> {
        const endpoint = SynapseAdminApi.USERS_DETAILS.replace("{userId}", encodeURIComponent(userId));
        const response = await this.httpClient.get<{
            status: string;
            data?: IAdminUser;
            error?: string;
        }>(endpoint, {});

        try {
            return handleApiResponse(response, "Failed to get user detail");
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.toLowerCase().includes("failed") || error.message.toLowerCase().includes("not found"))
            ) {
                return null;
            }
            throw error;
        }
    }

